    static Drawable drawable(String[] paths) {
        return drawable(paths, 64, 64, false);
    }

    static Drawable drawable(String[] paths, float vw, float vh, boolean evenOdd) {
        return drawable(paths, vw, vh, evenOdd, 0xFFFFFFFF);
    }

    // Drawn fitted and centred in its bounds, keeping the view box's proportions.
    static Drawable drawable(String[] paths, final float vw, final float vh, boolean evenOdd, final int color) {
        final Path[] built = new Path[paths.length];
        for (int i = 0; i < paths.length; i++) {
            built[i] = parse(paths[i]);
            if (evenOdd) built[i].setFillType(Path.FillType.EVEN_ODD);
        }
        return new Drawable() {
            private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
            { paint.setColor(color); }
            @Override public void draw(Canvas c) {
                android.graphics.Rect b = getBounds();
                int save = c.save();
                float k = Math.min(b.width() / vw, b.height() / vh);
                c.translate(b.left + (b.width() - vw * k) / 2f, b.top + (b.height() - vh * k) / 2f);
                c.scale(k, k);
                for (Path p : built) c.drawPath(p, paint);
                c.restoreToCount(save);
            }
            @Override public void setAlpha(int a) { paint.setAlpha(a); }
            @Override public void setColorFilter(ColorFilter f) { paint.setColorFilter(f); }
            @Override public int getOpacity() { return PixelFormat.TRANSLUCENT; }
        };
    }

    private static final Pattern TOKEN = Pattern.compile("[MmLlHhVvCcZz]|-?\\d*\\.?\\d+(?:[eE]-?\\d+)?");

    static Path parse(String d) {
        Path path = new Path();
        Matcher m = TOKEN.matcher(d);
        java.util.List<String> t = new java.util.ArrayList<>();
        while (m.find()) t.add(m.group());
        int i = 0;
        char cmd = 'M';
        float x = 0, y = 0, sx = 0, sy = 0;
        while (i < t.size()) {
            String s = t.get(i);
            if (Character.isLetter(s.charAt(0))) { cmd = s.charAt(0); i++; if (cmd == 'Z' || cmd == 'z') { path.close(); x = sx; y = sy; } continue; }
            boolean rel = Character.isLowerCase(cmd);
            switch (Character.toUpperCase(cmd)) {
                case 'M': { float nx = f(t, i++), ny = f(t, i++); if (rel) { nx += x; ny += y; } path.moveTo(nx, ny); x = sx = nx; y = sy = ny; cmd = rel ? 'l' : 'L'; break; }
                case 'L': { float nx = f(t, i++), ny = f(t, i++); if (rel) { nx += x; ny += y; } path.lineTo(nx, ny); x = nx; y = ny; break; }
                case 'H': { float nx = f(t, i++); if (rel) nx += x; path.lineTo(nx, y); x = nx; break; }
                case 'V': { float ny = f(t, i++); if (rel) ny += y; path.lineTo(x, ny); y = ny; break; }
                case 'C': {
                    float x1 = f(t, i++), y1 = f(t, i++), x2 = f(t, i++), y2 = f(t, i++), nx = f(t, i++), ny = f(t, i++);
                    if (rel) { x1 += x; y1 += y; x2 += x; y2 += y; nx += x; ny += y; }
                    path.cubicTo(x1, y1, x2, y2, nx, ny); x = nx; y = ny; break;
                }
                default: i++;
            }
        }
        return path;
    }

    private static float f(java.util.List<String> t, int i) { return Float.parseFloat(t.get(i)); }
